1456	/// Called when the terminal detects there is a password input prompt.
1457	fn passwordInput(self: *Surface, v: bool) !void {
1458	    {
1459	        self.renderer_state.mutex.lockUncancelable(global.io());
1460	        defer self.renderer_state.mutex.unlock(global.io());
1461	
1462	        // If our password input state is unchanged then we don't
1463	        // waste time doing anything more.
1464	        const old = self.io.terminal.flags.password_input;
1465	        if (old == v) return;
1466	
1467	        self.io.terminal.flags.password_input = v;
1468	    }
1469	
1470	    // Notify our apprt so it can do whatever it wants.
1471	    _ = self.rt_app.performAction(
1472	        .{ .surface = self },
1473	        .secure_input,
1474	        if (v) .on else .off,
1475	    ) catch |err| {
1476	        // We ignore this error because we don't want to fail this
1477	        // entire operation just because the apprt failed to set
1478	        // the secure input state.
1479	        log.warn("apprt failed to set secure input state err={}", .{err});
1480	    };
1481	
1482	    try self.queueRender();
1483	}
